// --- BOT LOGIC ---

const getBotFlavor = (setting: string, isSuccess: boolean) => {
    const universal = isSuccess 
        ? ["With perfect precision, ", "Guided by destiny, ", "Against all odds, ", "You find the perfect opening and ", "The stars align and "]
        : ["Distracted by a sudden noise, ", "You hesitate for a split second and ", "Bad luck strikes! ", "Gravity becomes your enemy and ", "Hubris is your downfall and "];
    return universal[Math.floor(Math.random() * universal.length)];
};

const client = new Client({ intents: [GatewayIntentBits.Guilds] });

const channelModes = new Map<string, 'fail' | 'success'>();
const channelSettings = new Map<string, string>();
const channelSystems = new Map<string, string>();

const commands = [
    new SlashCommandBuilder()
        .setName('fumble')
        .setDescription('Generate a Critical outcome')
        .addStringOption(option => 
            option.setName('type')
                .setDescription('Type of action')
                .setRequired(true)
                .addChoices(
                    { name: 'Melee', value: 'Melee' },
                    { name: 'Ranged', value: 'Ranged' },
                    { name: 'Spell', value: 'Spell' },
                    { name: 'Social', value: 'Social' },
                    { name: 'Skill', value: 'Skill' }
                ))
        .addIntegerOption(option => 
            option.setName('tone')
                .setDescription('Chaos/Glory Level (0-100). Default: 50')
                .setMinValue(0)
                .setMaxValue(100)),
    new SlashCommandBuilder()
        .setName('mode')
        .setDescription('Switch between Fumble (Nat 1) and Success (Nat 20)')
        .addStringOption(option =>
            option.setName('mode')
                .setDescription('The mode to set')
                .setRequired(true)
                .addChoices(
                    { name: 'Failure (Nat 1)', value: 'fail' },
                    { name: 'Success (Nat 20)', value: 'success' }
                )),
    new SlashCommandBuilder()
        .setName('setting')
        .setDescription('Change the campaign flavor')
        .addStringOption(option =>
            option.setName('flavor')
                .setDescription('Campaign Setting')
                .setRequired(true)
                .addChoices(...campaignSettings.slice(0, 25).map(s => ({ name: s, value: s })))),
    new SlashCommandBuilder()
        .setName('system')
        .setDescription('Change the ruleset')
        .addStringOption(option =>
            option.setName('ruleset')
                .setDescription('Game System')
                .setRequired(true)
                .addChoices(...gameSystems.map(s => ({ name: s.label, value: s.id }))))
].map(command => command.toJSON());

client.on('interactionCreate', async interaction => {
    if (!interaction.isChatInputCommand()) return;

    const { commandName, channelId } = interaction;
    const currentMode = channelModes.get(channelId) || 'fail';
    const currentSetting = channelSettings.get(channelId) || campaignSettings[0];
    const currentSystem = channelSystems.get(channelId) || 'dnd5e';

    if (commandName === 'mode') {
        const newMode = interaction.options.getString('mode') as 'fail' | 'success';
        channelModes.set(channelId, newMode);
        await interaction.reply(`🎲 **Mode updated!** Rolling for **${newMode === 'fail' ? 'Critical Failures (Nat 1)' : 'Critical Successes (Nat 20)'}**.`);
    } 
    else if (commandName === 'setting') {
        const newSetting = interaction.options.getString('flavor') || campaignSettings[0];
        channelSettings.set(channelId, newSetting);
        await interaction.reply(`🌍 **Setting updated!** Flavor set to **${newSetting}**.`);
    }
    else if (commandName === 'system') {
        const newSystem = interaction.options.getString('ruleset') || 'dnd5e';
        channelSystems.set(channelId, newSystem);
        const sysLabel = gameSystems.find(s => s.id === newSystem)?.label;
        await interaction.reply(`📚 **System updated!** Ruleset set to **${sysLabel}**.`);
    }
    else if (commandName === 'fumble') {
        const type = interaction.options.getString('type') || 'Melee';
        const tone = interaction.options.getInteger('tone') ?? 50;
        
        const dataSource = currentMode === 'fail' ? fumbles : successes;
        
        let criteriaPool = dataSource.filter(f => f.type === type);
        criteriaPool = criteriaPool.filter(f => tone >= f.minTone && tone <= f.maxTone);
        criteriaPool = criteriaPool.filter(f => {
            const isUniversal = !f.systems || f.systems.length === 0;
            if (currentSystem === 'generic') return isUniversal;
            return isUniversal || f.systems?.includes(currentSystem);
        });

        // Fallbacks
        if (criteriaPool.length === 0) {
             criteriaPool = dataSource.filter(f => f.type === type && (!f.systems || f.systems.includes(currentSystem)));
        }
        if (criteriaPool.length === 0) {
             criteriaPool = dataSource.filter(f => f.type === type && !f.systems);
        }

        if (criteriaPool.length === 0) {
            await interaction.reply({ content: "Could not find a suitable result for this criteria.", ephemeral: true });
            return;
        }

        const result = criteriaPool[Math.floor(Math.random() * criteriaPool.length)];
        const flavor = getBotFlavor(currentSetting, currentMode === 'success');
        
        const emojiMap: Record<string, string> = { 'Melee': '⚔️', 'Ranged': '🏹', 'Spell': '✨', 'Social': '💬', 'Skill': '🎲' };
        const titleEmoji = currentMode === 'success' ? '🏆' : '💀';
        const color = currentMode === 'success' ? 0xFFD700 : 0xDC143C;

        await interaction.reply({
            embeds: [{
                title: `${titleEmoji} ${currentMode === 'success' ? 'CRITICAL SUCCESS' : 'CRITICAL FAILURE'}`,
                description: `**${flavor}${result.text}**`,
                color: color,
                fields: [
                    { name: 'Type', value: `${emojiMap[type]} ${type}`, inline: true },
                    { name: 'Level', value: `${tone}/100`, inline: true }
                ],
                footer: { text: `System: ${currentSystem} | Setting: ${currentSetting}` }
            }]
        });
    }
});

client.once('ready', async () => {
    console.log(`Logged in as ${client.user?.tag}!`);
    const rest = new REST({ version: '10' }).setToken(process.env.DISCORD_TOKEN!);
    try {
        console.log('Refreshing application (/) commands...');
        await rest.put(Routes.applicationCommands(client.user!.id), { body: commands });
        console.log('Successfully reloaded commands.');
    } catch (error) {
        console.error(error);
    }
});

if (!process.env.DISCORD_TOKEN) {
    console.log("⚠️ DISCORD_TOKEN not found in env. Please check your .env file.");
} else {
    client.login(process.env.DISCORD_TOKEN);
}
